import logging
import re

from moler.exceptions import ParsingDone, CommandFailure
from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'dawid.gwizdz@nokia.com'


class CmConnect(GenericRtg):
    """Command for execute sector/tgr connect procedure."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Cm connect command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CmConnect, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.connecting_devices = set()

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "cm connect"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        self._log(lvl=logging.DEBUG, msg=f"cm connect got a new line = {line!r}")
        if is_full_line:
            try:
                self._parse_connecting_device(line)
                self._parse_connected(line)
                self._parse_error_connecting(line)
                self._parse_not_receiving_overhead_messages(line)
                self._parse_error_sending__b_sector_status_req(line)
                self._parse_sector_is_not_synchronized(line)
                self._log(lvl=logging.DEBUG, msg='Parsing was not finished.')
            except ParsingDone:
                pass
        return super(CmConnect, self).on_new_line(line, is_full_line)

    # Example line: Connection Manager: Connecting to SECTOR-1@1 10.60.0.10:8004
    _re_connecting_device = re.compile(r'Connection Manager:\s*Connecting to (?P<DEVICE>.*) .*$')

    def _parse_connecting_device(self, line):
        """
        Parse line contains device which is connecting.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_connecting_device, line):
            self.connecting_devices.add(self._regex_helper.group('DEVICE'))
            raise ParsingDone

    _re_connected = re.compile(r'^Connection Manager: All SECTORs and TGRs connected$')

    def _parse_connected(self, line):
        """
        Parse line contains informing if all devices are connected.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_connected, line):
            self.current_ret['STATUS'] = 'connected'
            self.current_ret['connected_devices'] = self.connecting_devices
            raise ParsingDone

    # Example line: Connection Manager: Error connecting to UESIM-MMI-CTRL-2 10.60.0.15:8498, disconnecting all ...
    # Example line: Connection Manager: Error connecting to SECTOR-111@2 10.0.1.1:8007, propably UEsim or host are down,
    # disconnecting all ...
    _re_error_connecting = \
        re.compile(r'^Connection Manager: Error connecting to (?P<DEVICE>.*?) [\d.:]*,.*?disconnecting all \.\.\.$')

    def _parse_error_connecting(self, line):
        """
        Parse line contains informing about error connecting.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_error_connecting, line):
            self.current_ret['STATUS'] = 'disconnected'
            self.current_ret['first_not_connected_device'] = self._regex_helper.group('DEVICE')
            self.set_exception(CommandFailure(self, f"Error connecting to {self._regex_helper.group('DEVICE')}"))
            raise ParsingDone

    # Example line: Connection Manager: Sector Cleanup: SECTOR-1@1 is not receiving overhead messages
    _re_not_receiving_overhead_messages = \
        re.compile('^Connection Manager: Sector Cleanup: (?P<DEVICE>.*) is not receiving overhead messages$')

    def _parse_not_receiving_overhead_messages(self, line):
        """
        Parse line contains information about not receiving overhead messages.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_not_receiving_overhead_messages, line):
            self.current_ret['STATUS'] = 'disconnected'
            self.current_ret['first_not_connected_device'] = self._regex_helper.group('DEVICE')
            self.set_exception(CommandFailure(self, f"{self._regex_helper.group('DEVICE')} is not receiving overhead messages."))
            raise ParsingDone

    # Example line: Connection Manager: Sector Cleanup: Error sending BSectorStatusReq to SECTOR-1@1
    _re_error_sending_bsectorstatusreq = \
        re.compile('^Connection Manager: Sector Cleanup: Error sending BSectorStatusReq to (?P<DEVICE>.*)$')

    def _parse_error_sending__b_sector_status_req(self, line):
        """
        Parse line contains information about sending BSectorStatusReq messages.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_error_sending_bsectorstatusreq, line):
            self.current_ret['STATUS'] = 'disconnected'
            self.current_ret['first_not_connected_device'] = self._regex_helper.group('DEVICE')
            self.set_exception(CommandFailure(self, f"Error sending BSectorStatusReq to {self._regex_helper.group('DEVICE')}."))
            raise ParsingDone

    # Example line: Connection Manager: Sector Cleanup: SECTOR-21@2 is not synchronized
    _re_sector_not_synchronized = \
        re.compile('^Connection Manager: Sector Cleanup: (?P<DEVICE>.*) is not synchronized$')

    def _parse_sector_is_not_synchronized(self, line):
        """
        Parse line contains information about sector cleanup - sector not being synchronized.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_sector_not_synchronized, line):
            self.current_ret['STATUS'] = 'disconnected'
            self.current_ret['first_not_connected_device'] = self._regex_helper.group('DEVICE')
            self.set_exception(CommandFailure(self, f"Error, {self._regex_helper.group('DEVICE')} is not synchronized."))
            raise ParsingDone


